import { Training } from '../../domain';
import { TrainingCard } from '../Cards';
import { Empty } from '../Empty';
import {
  StyledSearchResults,
  StyledSearchResultsContainer,
  StyledTotalResults,
  StyledTotalResultsContainer,
} from './SearchResults.styles';

export const SearchResults = ({ trainings }: { trainings: Training[] }) => {
  const isEmpty = trainings.length === 0;

  if (isEmpty) {
    return (
      <Empty
        type="search-empty"
        title="No Results Found"
        description="Please try searching with a different name!"
      />
    );
  }

  return (
    <StyledSearchResultsContainer>
      <StyledTotalResultsContainer>
        <StyledTotalResults>{trainings.length}</StyledTotalResults>{' '}
        {trainings.length === 1 ? 'result' : 'results'} found
      </StyledTotalResultsContainer>
      <StyledSearchResults>
        {trainings.map((training) => (
          <TrainingCard key={training.id} training={training} />
        ))}
      </StyledSearchResults>
    </StyledSearchResultsContainer>
  );
};
